INSERT OR IGNORE INTO review_work_items (work_item_id,claim_id,candidate_id,promotion_id,origin_kind,work_type,status,required_matching_reviews,max_reviews,created_at)
SELECT 'work_' || claim.claim_id,claim.claim_id,NULL,NULL,'existing_ledger_claim',
  'claim_adjudication','ready',2,4,'2026-09-21T00:00:00.000Z'
FROM claims claim
WHERE claim.visibility='draft'
  AND EXISTS (SELECT 1 FROM public_research_briefs brief WHERE brief.claim_id=claim.claim_id);
